const response = $input.first().json;
const base64Data = response.Files[0].FileData;
const text = Buffer.from(base64Data, 'base64').toString('utf8');

return [{ json: { text } }];

const roleKeywords = {
  'Backend Developer': ['backend developer', 'backend dev', 'node developer', 'node.js developer'],
  'Graphic Designer': ['graphic designer', 'graphics designer', 'designer role'],
  'Account Manager': ['account manager', 'account management']
};

const text = `${$json.subject || ''} ${$json.text || ''}`.toLowerCase();

let matchedRole = null;
for (const [role, keywords] of Object.entries(roleKeywords)) {
  if (keywords.some(k => text.includes(k))) {
    matchedRole = role;
    break;
  }
}

return [{
  json: {
    email: $input.first().json.email,
    roleApplied: matchedRole || 'unspecified'
  },
  binary: $binary
}];

const items = $input.all();
const grouped = {};

items.forEach(item => {
  const role = item.json.roleApplied;
  if (!grouped[role]) grouped[role] = [];
  grouped[role].push(item.json);
});

const result = [];
Object.values(grouped).forEach(group => {
  group.sort((a, b) => b.score - a.score);
  group.forEach((candidate, index) => {
    result.push({ json: { ...candidate, rank: index + 1 } });
  });
});

return result;

const items = $input.all();
const role = items[0].json.roleApplied || $('Rank per Role').first().json.roleApplied;

let message = `📋 *Shortlist Ready: ${role}*\n\nHere are the top-ranked candidates for this role. Scores and summaries are provided so you can sanity-check the reasoning — not just the number.\n\n`;

items.forEach(item => {
  const full = $('Rank per Role').all().find(r => r.json.candidateEmail === item.json.candidateEmail).json;
  message += `*#${item.json.rank} — ${item.json.candidateEmail}* | Score: ${full.score}/100\n${full.summary}\n✅ Must-haves met: ${full.musthavemet}\n⚠️ Red flags: ${full.redflag}\nResume: ${full.CV}\n\n`;
});

message += `Please review before moving anyone forward — the ranking is a starting point, not the final word.`;

return [{ json: { message } }];

